package com.dy.artisan3d.data.repositoryimport com.dy.artisan3d.data.mapper.toDomainimport com.dy.artisan3d.data.model.artisan.media.ArtisanMediaResponseimport com.dy.artisan3d.domain.model.artisan.ArtisanMediaimport com.dy.artisan3d.domain.repository.ArtisanMediaRepositoryimport com.dy.artisan3d.util.Constants.BASE_URLimport com.dy.artisan3d.util.safeApiCallimport io.ktor.client.HttpClientimport io.ktor.client.call.bodyimport io.ktor.client.request.getimport io.ktor.client.request.parameterclass ArtisanMediaRepositoryImpl(    private val httpClient: HttpClient // Ktor ishlatayotgan bo'lsangiz) : ArtisanMediaRepository {    override suspend fun getMediaList(page: Int, lang: String): Result<List<ArtisanMedia>> {        val response: Result<ArtisanMediaResponse> = safeApiCall {            httpClient.get(BASE_URL + "media") {                parameter("page", page)            }.body()        }        return response.map { response ->            response.data.map { dto ->                dto.toDomain(lang)            }        }    }}